"""共用轮次原语 — 5.11 (R50(d)) 的唯一循环实现。

``routes/task.py`` 的 ``run_rounds()`` 与 ``ops/normal_fight.run_for_times()``
都以本模块的 :func:`run_round_loop` 为底座，避免再出现三份各自为战的
循环。原语只负责「轮次控制」，不认识游戏页面、任务管理器或 API：

- 每轮开始前检查停止信号；
- 每轮结束后识别船坞满：解装成功的轮**不占次数**并立即重试，
  解装失败则终止剩余轮次；
- 把异常/结果归一化交给调用方的回调；
- 可选轮间 ``gap``。

「船坞满轮」的判定与 ``scheduler._run_task`` 既有语义一致：只有本轮
**全部**结果都是 ``DOCK_FULL + dock_full_destroyed`` 才视为「已解装、
未开打、不计数」。
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any

from autowsgr.infra.logger import get_logger
from autowsgr.types import ConditionFlag


if TYPE_CHECKING:
    from collections.abc import Callable


_log = get_logger('ops.rounds')

# 与前端/任务状态共享的稳定 stop_reason 值。
STOP_REASON_STOPPED = 'stopped'
STOP_REASON_DOCK_FULL = 'dock_full'
STOP_REASON_STOP_CONDITION = 'stop_condition'
STOP_REASON_RESOURCE_EXHAUSTED = 'resource_exhausted'
STOP_REASON_ERROR = 'error'
STOP_REASON_UNKNOWN_PAGE = 'unknown_page'

# 防止「解装成功但永远开不了打」的病态循环；正常一轮只会撞 1-2 次。
DEFAULT_MAX_DOCK_RETRIES = 100

_RESOURCE_FIELDS = (
    ('fuel', '燃料'),
    ('ammo', '弹药'),
    ('steel', '钢材'),
    ('aluminum', '铝材'),
)


def _resource_value(source: Any, field: str) -> Any:
    """读取资源/阈值字段；兼容 dataclass、Pydantic 模型与 dict。"""
    if source is None:
        return None
    if isinstance(source, dict):
        return source.get(field)
    return getattr(source, field, None)


def evaluate_resource_thresholds(resources: Any, thresholds: Any) -> str | None:
    """比较四项基础资源与最低保留量，返回违反说明；无违反返回 ``None``。

    ``resources`` 来自 ``GameContext.resources``（``/api/game/context``
    序列化的同一份数据）。四项全为 0 时视为「尚未从画面填充」，不做判断，
    避免默认零值把用户任务误停。
    """
    if resources is None or thresholds is None:
        return None

    values: dict[str, int] = {}
    for field, _label in _RESOURCE_FIELDS:
        try:
            values[field] = int(_resource_value(resources, field))
        except (TypeError, ValueError):
            _log.debug('[Rounds] 资源 {} 不是整数，跳过阈值判断', field)
            return None

    if all(value <= 0 for value in values.values()):
        _log.debug('[Rounds] 资源尚未填充（四项均为 0），跳过阈值判断')
        return None

    violations: list[str] = []
    for field, label in _RESOURCE_FIELDS:
        raw_minimum = _resource_value(thresholds, field)
        try:
            minimum = int(raw_minimum) if raw_minimum is not None else 0
        except (TypeError, ValueError):
            minimum = 0
        if minimum > 0 and values[field] < minimum:
            violations.append(f'{label} {values[field]} < {minimum}')
    return '、'.join(violations) or None


@dataclass(frozen=True)
class ExceptionDecision:
    """异常回调的返回值。

    ``break_loop`` 为 ``False`` 且 ``count_round`` 为 ``True`` 时，调用方
    把这次异常当作「失败的一轮」继续下一轮（保留 routes 旧行为）；需要
    中止剩余轮次时把 ``break_loop`` 置为 ``True``。
    """

    results: list[Any] = field(default_factory=list)
    break_loop: bool = False
    stop_reason: str | None = None
    error: str | None = None
    count_round: bool = True


@dataclass(frozen=True)
class RoundLoopOutcome:
    """共用轮次原语的执行结果。"""

    results: list[Any]
    stop_reason: str | None = None
    error: str | None = None


def is_dock_full_result(result: Any) -> bool:
    """结果是否因船坞满而未开打（兼容 CombatResult 与 dict）。"""
    flag = result.get('flag') if isinstance(result, dict) else getattr(result, 'flag', None)
    return flag == ConditionFlag.DOCK_FULL or flag == ConditionFlag.DOCK_FULL.value


def is_dock_full_resolved(result: Any) -> bool:
    """船坞满轮是否已经成功解装/强化（未开打但可立即重试）。"""
    if isinstance(result, dict):
        return bool(result.get('dock_full_destroyed'))
    return bool(getattr(result, 'dock_full_destroyed', False))


def run_round_loop(
    round_func: Callable[[int], Any],
    times: int,
    *,
    stop_requested: Callable[[], bool] | None = None,
    on_round_start: Callable[[int, int], None] | None = None,
    each_round_guard: Callable[[int], str | None] | None = None,
    normalize: Callable[[Any, int], list[Any]] | None = None,
    on_round_complete: Callable[[list[Any]], None] | None = None,
    is_dock_full: Callable[[Any], bool] = is_dock_full_result,
    is_dock_resolved: Callable[[Any], bool] = is_dock_full_resolved,
    on_exception: Callable[[Exception, int], ExceptionDecision | None] | None = None,
    stop_after: Callable[[list[Any]], str | None] | None = None,
    gap: float = 0.0,
    sleep: Callable[[float], None] = time.sleep,
    max_dock_retries: int = DEFAULT_MAX_DOCK_RETRIES,
) -> RoundLoopOutcome:
    """执行 ``times`` 个「真实开打」的轮次。

    Parameters
    ----------
    round_func:
        执行一轮；参数是当前计数的轮次（1-based）。船坞满重试时收到同一个
        轮次号。
    times:
        需要完成的真实轮次。船坞满且解装成功的尝试不计入。
    stop_requested:
        每轮开始前调用；返回 ``True`` 时以 ``stop_reason='stopped'`` 结束。
    on_round_start:
        ``(current_round, total_rounds)``；用于上报进度/日志。
    each_round_guard:
        每轮开始前调用；返回非空 ``stop_reason`` 即中止剩余轮次
        （资源阈值等轮前守卫使用）。
    normalize:
        ``(raw_result, current_round)`` → 结果列表。默认把返回值当成单结果。
    on_round_complete:
        每产生一批「计入轮次」的结果时调用一次（失败轮也会调用）。
    is_dock_full / is_dock_resolved:
        船坞满判定；默认适配 CombatResult 与 ``convert_combat_result`` 的 dict。
    on_exception:
        异常转换回调；返回 ``None`` 时原样抛出。任务层用它把异常落成一轮
        失败结果，ops 层不传则保持「异常向上抛」的旧行为。
    stop_after:
        一批结果计入轮次后调用；返回非空值即终止循环（如等级停止条件）。
    gap:
        两个**真实轮次**之间的间隔（秒）。
    max_dock_retries:
        连续船坞满重试上限，防止病态循环。

    Returns
    -------
    RoundLoopOutcome
        只包含计入轮次的结果；解装成功的船坞满轮不放进 ``results``，
        失败的船坞满轮会作为一条失败结果保留。
    """
    if times <= 0:
        return RoundLoopOutcome(results=[])

    results: list[Any] = []
    completed = 0
    dock_retries = 0
    stop_reason: str | None = None
    error: str | None = None

    while completed < times:
        if stop_requested is not None and stop_requested():
            stop_reason = STOP_REASON_STOPPED
            _log.info('[Rounds] 收到停止请求, 中止剩余轮次 (已完成 {})', completed)
            break

        if each_round_guard is not None:
            guard_reason = each_round_guard(completed + 1)
            if guard_reason:
                stop_reason = guard_reason
                _log.warning(
                    '[Rounds] 轮前守卫中止: {} (已完成 {})',
                    guard_reason,
                    completed,
                )
                break

        current_round = completed + 1
        if on_round_start is not None:
            on_round_start(current_round, times)

        try:
            raw = round_func(current_round)
        except Exception as exc:  # noqa: BLE001 - 由调用方的 on_exception 决定语义
            if on_exception is None:
                raise
            decision = on_exception(exc, current_round)
            if decision is None:
                raise
            if decision.results:
                results.extend(decision.results)
                if on_round_complete is not None:
                    on_round_complete(decision.results)
            if decision.error is not None:
                error = decision.error
            if decision.stop_reason is not None:
                stop_reason = decision.stop_reason
            if decision.break_loop:
                break
            if decision.count_round:
                completed += 1
                if gap > 0 and completed < times:
                    sleep(gap)
            continue

        items = normalize(raw, current_round) if normalize is not None else [raw]
        items = [item for item in items if item is not None]
        if not items:
            stop_reason = STOP_REASON_ERROR
            error = '本轮未返回任何结果'
            _log.error('[Rounds] {}', error)
            break

        dock_full = any(is_dock_full(item) for item in items)
        dock_resolved = dock_full and all(
            is_dock_full(item) and is_dock_resolved(item) for item in items
        )

        if dock_resolved:
            dock_retries += 1
            if dock_retries > max_dock_retries:
                stop_reason = STOP_REASON_DOCK_FULL
                error = f'船坞已满且解装重试超过 {max_dock_retries} 次, 已停止任务'
                _log.error('[Rounds] {}', error)
                break
            _log.warning(
                '[Rounds] 船坞已满但解装成功, 本轮不占次数, 立即重试 (第 {} 轮)',
                current_round,
            )
            continue

        results.extend(items)
        if on_round_complete is not None:
            on_round_complete(items)
        completed += 1

        if dock_full:
            stop_reason = STOP_REASON_DOCK_FULL
            error = '船坞已满且解装失败, 已停止任务并告警'
            _log.error('[Rounds] {}', error)
            break

        if stop_after is not None:
            reason = stop_after(items)
            if reason:
                stop_reason = reason
                break

        if gap > 0 and completed < times:
            sleep(gap)

    return RoundLoopOutcome(results=results, stop_reason=stop_reason, error=error)
